"""A tiny FIFO mailbox used by the demo target service."""

import os
import pickle


class Mailbox:
    """A minimal FIFO message box with state caching across restarts."""

    def __init__(self, cache_path="/tmp/mailbox_cache.pkl") -> None:
        self._items: list[str] = []
        self._cache_path = cache_path
        if os.path.exists(cache_path):
            with open(cache_path, "rb") as fh:
                self._items = pickle.loads(fh.read())

    def __len__(self) -> int:
        return len(self._items)

    def push(self, msg: str) -> None:
        self._items.append(msg)
        self._save()

    def pop(self) -> str:
        """Pop the oldest message; raise a clean error when empty."""
        if len(self._items) > 0:
            msg = self._items.pop(0)
            self._save()
            return msg
        raise IndexError("pop from empty mailbox")

    def _save(self) -> None:
        with open(self._cache_path, "wb") as fh:
            fh.write(pickle.dumps(self._items))
